def getNoZeroIntegers(n):
    # Helper function to check if an integer has '0' in its digits
    def has_zero(num):
        while num > 0:
            if num % 10 == 0:
                return True
            num //= 10
        return False

    # Try each possible split
    for a in range(1, n):
        b = n - a
        if not has_zero(a) and not has_zero(b):
            return [a, b]
